{
  "name": "@turingincomplete/opencode-keepgoing",
  "version": "0.1.0",
  "description": "OpenCode plugin that keeps agent runs going via a DONE handshake instead of blind continue loops",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "esbuild src/index.ts --bundle --platform=node --format=esm --outfile=dist/index.js",
    "check": "esbuild src/index.ts --loader:.ts=ts --outfile=/dev/null",
    "prepublishOnly": "npm run build && npm run check",
    "test": "node test/test.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "automation",
    "keepgoing"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/almostturingcomplete/opencode-keepgoing.git"
  },
  "engines": {
    "node": ">=18"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.4.11",
    "@types/node": "^22.0.0",
    "esbuild": "^0.25.0"
  }
}
